//! Response body produced by securite middlewares.

use std::pin::Pin;
use std::task::{Context, Poll};

use bytes::Bytes;
use http_body::{Body, Frame, SizeHint};
use pin_project_lite::pin_project;

pin_project! {
    /// Either the body produced by your service or a small rejection body
    /// generated by a guard.
    ///
    /// It implements [`http_body::Body`] with the same error type as the inner
    /// body, so it works transparently with axum, hyper and tonic.
    #[project = SecureBodyProj]
    #[allow(missing_docs)]
    pub enum SecureBody<B> {
        /// The body of the wrapped service.
        Inner { #[pin] body: B },
        /// A complete in-memory body (rejections).
        Full { data: Option<Bytes> },
    }
}

impl<B> SecureBody<B> {
    /// Wraps the inner service body.
    pub fn inner(body: B) -> Self {
        Self::Inner { body }
    }

    /// Creates a complete body from bytes.
    pub fn full(data: Bytes) -> Self {
        Self::Full {
            data: if data.is_empty() { None } else { Some(data) },
        }
    }
}

impl<B> Body for SecureBody<B>
where
    B: Body<Data = Bytes>,
{
    type Data = Bytes;
    type Error = B::Error;

    fn poll_frame(
        self: Pin<&mut Self>,
        cx: &mut Context<'_>,
    ) -> Poll<Option<Result<Frame<Self::Data>, Self::Error>>> {
        match self.project() {
            SecureBodyProj::Inner { body } => body.poll_frame(cx),
            SecureBodyProj::Full { data } => Poll::Ready(data.take().map(|d| Ok(Frame::data(d)))),
        }
    }

    fn is_end_stream(&self) -> bool {
        match self {
            SecureBody::Inner { body } => body.is_end_stream(),
            SecureBody::Full { data } => data.is_none(),
        }
    }

    fn size_hint(&self) -> SizeHint {
        match self {
            SecureBody::Inner { body } => body.size_hint(),
            SecureBody::Full { data } => {
                SizeHint::with_exact(data.as_ref().map_or(0, |d| d.len() as u64))
            }
        }
    }
}

impl<B> Default for SecureBody<B> {
    fn default() -> Self {
        Self::Full { data: None }
    }
}
